from pathlib import Path

root = Path(__file__).resolve().parent.parent
build = root.parent / 'local-build-joint-request-economics-20261006-final'
old = root.parent / 'lightwork-pr2519-layer-20260928/.browser-runtime'
server = (old / 'p09_request_program_server.py').read_text(encoding='utf-8').replace('8857', '8871')
server = server.replace(' from maverick import config,world_model,llm',
    ' from maverick import config,world_model,llm\n import maverick,maverick_dashboard\n installed=Path(os.environ["TASK_INSTALLED_PROOF_RUNTIME"])\n assert Path(maverick.__file__).is_relative_to(installed)\n assert Path(maverick_dashboard.__file__).is_relative_to(installed)')
server = server.replace('request_program = true', 'request_program = true\\nprocedure_interactions = true')
start = server.index(" with tenant_scope(tenant='browser-workspace'):")
end = server.index(" @dashboard.app.get('/auth/invite/__fixture/request/{actor}')", start)
replacement = ''' with tenant_scope(tenant='browser-workspace'):
  spec={'inputs':{'amount':{'type':'integer','min':999999999998,'max':1000000000000}},'output_type':'integer','constants':[1000000000000]}
  artifact=synthesize(spec,[{'inputs':{'amount':x},'output':x*1000000000000} for x in (999999999998,999999999999,1000000000000)])
  flow=Flow(id='exact-rule-results',name='Calculate a complete allowance',owner=actors['owner'],start='multiply',nodes={'multiply':FlowNode(id='multiply',kind='agent',learned_fallback=False,brief='Multiply the entered amount by its full allowance',label='Full allowance',output='answer')})
  flow=attach_learned_operator(flow,'multiply',artifact);flow=store.save_flow(flow);publication=store.publish_flow(flow.id,expected_version=flow.version,expected_revision=flow.revision);practices=[]
  for amount in (999999999999,1000000000000):
   original=store.FlowRun(run_id=store.new_run_id(),flow_id=flow.id,status='queued',owner=flow.owner,input_data={'amount':amount},definition_digest=publication['definition_digest'],definition_version=flow.version,definition_revision=flow.revision,release_digest=publication['release_digest'],release_id=publication['release_id'],subflow_digests=publication['subflow_digests']);store.save_run(original);original=execution.execute(flow,owner=flow.owner,run_id=original.run_id,data={'amount':amount},agent_runner=refusal,action_runner=refusal);assert original.status=='completed',original.error;practices.append({'id':original.run_id,'amount':amount})
'''
server = server[:start] + replacement + server[end:]
(build / 'installed_exact_rule_server.py').write_text(server, encoding='utf-8')
probe = '''const {chromium}=require(PLAYWRIGHT),fs=require('fs'),assert=require('assert/strict');
const base='http://127.0.0.1:8871',api='/api/v1/learning/request-program',rq='/api/v1/learning/rule-requalification';
(async()=>{const b=await chromium.launch(),c=await b.newContext({baseURL:base,viewport:{width:320,height:780},extraHTTPHeaders:{Origin:base,'X-Lightwork-Expected-Tenant':'browser-workspace'}}),p=await c.newPage(),errors=[],proof={};p.on('pageerror',e=>errors.push(String(e)));await c.request.get('/auth/invite/__fixture/request/owner');const state=async()=>{const r=await c.request.get('/__browser_fixture/request/state');assert.equal(r.status(),200);return r.json()},s=await state(),evidence=[];
await p.goto('/learning/recheck-rules?workflow='+s.flow);const ready=()=>p.waitForFunction(()=>document.getElementById('rule-requalification').getAttribute('aria-busy')==='false');await ready();
for(const row of s.practices){await p.locator('[name=practice]').selectOption(row.id);await p.locator('#rq-retain').click();await p.locator('#rq-review input').waitFor();await p.locator('#rq-review input').check();let reply=p.waitForResponse(r=>r.url().endsWith(rq+'/apply'));await p.getByRole('button',{name:'Confirm complete evidence check',exact:true}).click();let r=await reply;assert.equal(r.status(),200,await r.text());let v=await r.json();assert(v.confirmed);evidence.push({id:v.id,answer:(BigInt(row.amount)*1000000000000n).toString()});await ready();}
await p.goto('/learning/request-program?flow='+s.flow);const idle=()=>p.waitForFunction(()=>document.getElementById('request-program').getAttribute('aria-busy')==='false');await idle();assert.equal(await p.locator('#rp-error').innerText(),'');await p.locator('#rp-description').fill('Keep the complete allowance without rounding');await p.locator('#rp-steps input[value=multiply]').check();await p.locator('#rp-output').selectOption('answer');for(const row of evidence){const box=p.locator('[data-evidence="'+row.id+'"]');await box.locator('[data-selected]').check();await box.locator('[data-expected]').fill(row.answer);}await p.locator('[data-key=amount]').fill('999999999999');let reply=p.waitForResponse(r=>r.url().endsWith(api+'/review'));await p.locator('#rp-prepare').click();let r=await reply;assert.equal(r.status(),200,await r.text());let reviewed=await r.json();assert.match(await p.locator('#rp-preview').innerText(),/1000000000000000000000000/);await p.locator('#rp-preview input').check();reply=p.waitForResponse(r=>r.url().endsWith(api+'/apply'));await p.getByRole('button',{name:'Confirm calculation for this request',exact:true}).click();r=await reply;assert.equal(r.status(),200,await r.text());let v=await r.json();assert(v.confirmed&&v.result.agreement);assert.equal(v.result.answer,'999999999999000000000000');assert.equal(v.result.candidates.length,3);assert(v.result.candidates.every(row=>row.checks[1].value==='1000000000000000000000000'&&row.checks[1].expected==='1000000000000000000000000'));await idle();assert.match(await p.locator('#rp-result').innerText(),/999999999999000000000000/);let count=(await state()).construct;await p.reload();await idle();await p.locator('#rp-read').click();await idle();assert.match(await p.locator('#rp-result').innerText(),/999999999999000000000000/);r=await c.request.post(api+'/apply',{data:{token:reviewed.token,confirmed:true}});assert.equal(r.status(),200);assert.equal((await state()).construct,count);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.deepEqual(errors,[]);await p.screenshot({path:__dirname+'/exact-rule-result-phone.png',fullPage:true});proof.exact_answer=v.result.answer;proof.exact_maximum='1000000000000000000000000';proof.native_arrangements=3;proof.native_steps=v.result.native_steps;proof.reloaded_original_without_repeat=true;proof.providers=0;proof.page_errors=errors;fs.writeFileSync(__dirname+'/exact-rule-native-evidence.json',JSON.stringify(proof,null,2));await b.close();console.log('Fresh-installed ordinary exact25-digit desired answers, native request arrangements, complete original/reload/exact replay and320px passed.');})().catch(e=>{console.error(e);process.exit(1)});
'''
probe = probe.replace('PLAYWRIGHT', repr(str(old.parent / 'packages/maverick-dashboard/tests/browser/node_modules/@playwright/test').replace('\\', '/')))
(build / 'installed_exact_rule_native.cjs').write_text(probe, encoding='utf-8')
print('Prepared actual fresh-installed exact-result journey using the unchanged native learner and runner.')
